class item
{
public:
  enum signal_id_t
  {
    PARENT_SYNC_DUMMY = 26,
    PICKUP,
    USE,
    SCHWING,
    DETONATE,
    ARMED,
    N_SIGNALS
  };

  static void register_signals();
};

void item::register_signals()
{
  #define MAC(label,str)  signal_manager::inst()->insert( str, label );
  MAC( PICKUP, "item::PICKUP" )
  MAC( USE, "item::USE" )
  MAC( SCHWING, "item::SCHWING" )
  MAC( DETONATE, "item::DETONATE" )
  MAC( ARMED, "item::ARMED" )
  #undef MAC
}
